// Safeguard marker: INSTAOPS_V2_SCHEDULE — reads due SCHEDULED + LATER rows (Reels/Images/Carousels) from Supabase.
if (String($env.SCHEDULING_ENABLED || '').toLowerCase() !== 'true') {
  return [];
}
const now = Date.now();
const rows = $input.all().map(i => i.json || {});
const due = [];

for (const r of rows) {
  const status = String(r.status || '').toUpperCase();
  const mode = String(r.publish_mode || '').toUpperCase();
  const mediaType = String(r.media_type || 'REEL').toUpperCase();
  const pubMs = Date.parse(String(r.publish_at || ''));
  if (status !== 'SCHEDULED' || mode !== 'LATER') continue;
  if (!Number.isFinite(pubMs) || pubMs > now) continue;
  if (!r.revision || Number(r.approved_revision) !== Number(r.revision)) continue;
  const activeAssets = (Array.isArray(r.instaops_media_assets) ? r.instaops_media_assets : [])
    .filter(a => a.storage_status === 'ACTIVE')
    .sort((a, b) => Number(a.media_index || 0) - Number(b.media_index || 0));
  if (mediaType === 'CAROUSEL' && (activeAssets.length < 2 || activeAssets.length > 10)) continue;
  due.push({
    json: {
      action: 'PUBLISH',
      post_uuid: String(r.id),
      post_id: String(r.post_id),
      ig_user_id: String(r.ig_user_id || $env.INSTAGRAM_USER_ID || '17841453414532595'),
      media_type: mediaType,
      caption: String(r.caption || r.original_caption || ''),
      media_url: String(r.media_url || ''),
      media_items: activeAssets,
      reviewed_revision: String(r.revision),
      confirm: true,
      request_id: `sched_${r.post_id}_${Math.floor(now / 60000)}`,
      job_id: `job_sched_${r.post_id}`
    }
  });
}

return due.slice(0, 1);
